    md=[]
    for x in PARAGRAPHS:
        prefix='# ' if x['style']=='TITLE' else ('#'*(int(x['style'][-1])+1)+' ' if x['style'].startswith('HEADING') else '')
        md.append(prefix+x['text'].rstrip())
    (BASE/'MASTER_COURSE_DRAFT.md').write_text('\n\n'.join(md)+'\n',encoding='utf-8')
    print(json.dumps({'lessonsDrafted':len(LESSONS),'indexLessons':len(PLAN),'screens':sum(len(l['screens']) for l in LESSONS),'vocabularyEntries':len(WORDS),'exercises':sum(len(l['check'])+len(l['apply'])+sum('interaction' in s for s in l['screens']) for l in LESSONS),'paragraphs':len(PARAGRAPHS),'characters':sum(len(p['text'])+1 for p in PARAGRAPHS)},ensure_ascii=False))
